from lib import *
S = SS('n31')
steps = [
    step("decodeJSON 的流程:用 json.API.NewDecoder 创建解码器,按两个全局开关决定是否 UseNumber / DisallowUnknownFields,Decode 一次,成功后再 validate(obj)。实测默认很宽松:多余字段(含嵌套对象)被忽略;JSON 键不区分大小写({\"NAME\":…} 绑上 Name);重复键后者覆盖前者(name 最终是 b);Decode 只解第一个值,所以 `{…} {\"name\":\"second\"}`、`{…} garbage`、`{…}}}}` 都成功,后面的内容被忽略——对照 json.Unmarshal 同一个带垃圾的输入报 invalid character 'g' after top-level value;30.0 和 30.5 不能进 int 字段(报 cannot unmarshal number 30.0 …),字符串 \"30\" 也不行;null 对非指针字段保持零值。", t=tl(S(1)), mark=lidx(S(1), 'garbage', '{"name":"ann","age":30} {"name":"second"}', '"age":30.0', '"age":"30"', 'invalid character'), done=lidx(S(1), 'decoder.Decode(obj)', '"extra":1', '{"NAME":"ann"', '{"name":"a","name":"b"}'), kv=KV([['多余字段', '忽略'], ['末尾的垃圾', 'Decode 只解第一个值,不检查'], ['30.0 → int', '报错']], ['末尾的垃圾'])),
    step("binding.EnableDecoderDisallowUnknownFields = true 之后:未知字段报 json: unknown field \"extra\";嵌套对象里的 y、数组元素里的 q 同样报错;注意第一个错误之后字段仍被赋值(Name 保持 ann,Items 里的 z=1 已写入);键的大小写仍不敏感({\"NAME\":\"ann\"} 通过);末尾的垃圾依然通过。", t=tl(S(2)), mark=lidx(S(2), 'unknown field "extra"', 'unknown field "y"', 'unknown field "q"'), done=lidx(S(2), '{"name":"ann"}   ', '{"NAME":"ann"}', 'garbage'), kv=KV([['未知字段', 'json: unknown field "x"'], ['嵌套 / 数组里', '同样检查'], ['大小写与垃圾', '仍然宽松']], ['未知字段'])),
    step("UseNumber:interface{} / map[string]any 里的数字默认是 float64,9007199254740993 被解成 9.007199254740992e+15(丢了 1),12345678901234567890 解成 1.2345678901234567e+19;binding.EnableDecoderUseNumber = true 之后是 json.Number,保持 9007199254740993 与 12345678901234567890,1.10 也保持原样;声明为 int64 的字段不受影响,两种情况都是 9007199254740993。", t=tl(S(3)), mark=lidx(S(3), 'UseNumber=false', '对照'), done=lidx(S(3), 'UseNumber=true'), b=bars([['float64 解出的值(默认)', 9007199254740992, '9007199254740992'], ['真实值 / UseNumber 的值', 9007199254740993, '9007199254740993']], 9007199254740993, mark=[0], done=[1]), kv=KV([['默认', 'any 里的数字是 float64,大整数丢精度'], ['UseNumber', 'json.Number,保持原文'], ['类型化字段', '不受影响(int64 一直精确)']], ['默认'])),
    step("这两个开关是包级的全局变量,同一进程里所有路由、所有 JSON 绑定同时受影响:DisallowUnknownFields=false 时 /a(ShouldBindJSON)、/b(ShouldBindBodyWith)、/c(ShouldBind)都通过;改成 true 之后三个全部报 unknown field \"extra\",再改回去又都通过——运行中切换就是改变所有接口的行为。想让某一个接口严格,自己用 json.NewDecoder + DisallowUnknownFields,返回 400。", t=tl(S(4)), mark=lidx(S(4), 'DisallowUnknownFields=true', '400 json: unknown field'), done=lidx(S(4), 'DisallowUnknownFields=false'), kv=KV([['作用范围', '整个进程的所有 JSON 绑定'], ['切换', '运行中改会影响所有接口'], ['只想严格一个接口', '自己用 json.Decoder']], ['作用范围'])),
]
A = mkartn('n31', 31, 'Gin,JSON绑定,DisallowUnknownFields,UseNumber,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 JSON 绑定的严格程度:默认忽略多余字段、键不区分大小写、末尾的垃圾内容也通过;binding.EnableDecoderDisallowUnknownFields 让未知字段(含嵌套)报错但它是全局开关;UseNumber 让 any 里的大整数不丢精度(9007199254740993 默认被解成 …992)。',
    '前端多传了字段、写错了字段名,Gin 默认静悄悄地忽略;想要严格怎么办?大整数放在 map 里为什么变了?这篇用同一批请求体测 Gin 的 JSON 绑定默认有多宽松,打开 DisallowUnknownFields 与 UseNumber 后行为怎么变,以及这两个全局开关的影响面。',
    [('不报错', 'JSON 末尾带 garbage 时绑定的结果:只解第一个值,后面的内容被忽略'), ('…992 vs …993', 'any 字段里 9007199254740993 默认被解成的 float64 与 UseNumber 保持的值'), ('3 条路由', '全局开关同时影响 ShouldBindJSON、ShouldBindBodyWith、ShouldBind')],
    [('默认很宽松', '<p>Gin 的 <code>decodeJSON</code> 用 <code>Decode</code> 解码第一个 JSON 值,不检查后面还有没有内容,所以拼接了垃圾的请求体照样通过(与 <code>json.Unmarshal</code> 不同)。多余字段、大小写不一致、重复键都不报错;类型对不上(30.0 给 int、字符串给 int)则会报错。</p>'),
     ('严格模式', '<p>把 <code>binding.EnableDecoderDisallowUnknownFields</code> 设为 true,未知字段(包括嵌套对象和数组元素里的)会报 <code>json: unknown field</code>。但错误之前的字段已经赋值,并且键的大小写、末尾垃圾仍然宽松,所以它只是“防止拼错字段名”,不是完整的严格校验。</p>'),
     ('大整数', '<p><code>interface{}</code> 里的 JSON 数字默认是 <code>float64</code>,超过 2<sup>53</sup> 的整数会静默丢精度。<code>EnableDecoderUseNumber</code> 让它们变成 <code>json.Number</code> 保持原文。声明成 <code>int64</code> 的字段本来就精确,不需要这个开关;只在你确实要用 <code>map[string]any</code> 接收 ID 之类大整数时才有用。</p>'),
     ('全局开关的代价', '<p>这两个变量是包级别的,一旦设置,整个进程的所有 JSON 绑定都按新规则走,包括第三方库里调用的 <code>ShouldBindJSON</code>;在运行中切换更会让同一个接口前后行为不一致。只想让个别接口严格时,在该接口里自己创建 <code>json.Decoder</code> 最安全。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;binding 包的两个开关用代码赋值;JSON 编解码用 Gin 默认的 encoding/json(没有开 jsoniter / sonic 等构建标签);每种情形各一次',
     '没有验证:用 sonic、go-json 等替代 JSON 库(构建标签)时这些行为的差异——Gin 源码注释说它们对某些错误的处理不同;超大请求体、深层嵌套对象的限制;XML、YAML 绑定的严格程度;自定义 UnmarshalJSON 与这两个开关的交互'],
    'JSON 严格模式')
